#!/bin/sh
# Copyright (C) 2026 group24 AG
# SPDX-License-Identifier: AGPL-3.0-only
#
# Every source file carries the license header (Hauptplan E55). Generated files are exempt.
set -eu
cd "$(dirname "$0")/.."

missing=0
for f in $(find . \( -path ./web/node_modules -o -path ./web/dist -o -path ./.git \) -prune -o \
    -type f \( -name '*.go' -o -name '*.ts' -o -name '*.tsx' -o -name '*.js' -o -name '*.sql' \
    -o -name '*.sh' -o -name '*.yaml' -o -name '*.yml' -o -name 'Dockerfile' \) -print); do
  case "$f" in
    */pnpm-lock.yaml) continue ;; # generated by pnpm
    ./compose.override.yaml) continue ;; # local settings of one machine, never in Git
  esac
  if head -n 3 "$f" | grep -q -e 'Code generated' -e 'auto-generated'; then
    continue
  fi
  if ! head -n 6 "$f" | grep -q 'SPDX-License-Identifier: AGPL-3.0-only'; then
    echo "license header missing: $f"
    missing=1
  fi
done
case "$missing" in
  0) echo "license headers ok" ;;
  *) exit 1 ;;
esac
